"""Checkpoint informativeness screen + attempt-rate report (benchmark v2 proposal; NOT part of any frozen analysis).
Screen (uses ONLY scripted controls, never LLM output): headroom H = max gain over {gain_greedy, tensor_gain_greedy, analytic_ridge, oracle_restore} on the checkpoint's hidden-ID split;
keep a checkpoint if H >= 0.10 ('some scripted procedure shows there is room to improve it'). S3 (healthy) is reported separately because small headroom is its definition.
Validation (declared post-hoc, on the completed main study): do kept checkpoints give more discriminating, more repeatable LLM scores than dropped ones?"""
import json, sys
from pathlib import Path
import numpy as np, pandas as pd
ROOT = Path(__file__).resolve().parents[1]; sys.path.insert(0, str(ROOT))
from wsarena.analysis.metrics import load_runs
man = {e["sha256"][:12]: e for e in json.loads((ROOT / "configs/tasks/ckpt_manifest.json").read_text())["entries"] if e["status"] == "built"}
def get(exp):
    d = load_runs(ROOT / "runs" / exp); d["arm"] = d["run_id"].str.split("__").str[2]; d["ckpt_id"] = d["ckpt"].map(lambda c: man[c]["ckpt_id"] if c in man else None); return d.dropna(subset=["ckpt_id"])
b = pd.concat([get(e) for e in ("baselines-v1", "baselines-gain-v1", "baselines-greedy-v1", "baselines-ctrl2-v1", "baselines-mw-v1", "baselines-mwpeg-v1")])
g = b[b.arm.isin(["gain_greedy", "tensor_gain_greedy", "analytic_ridge", "oracle_restore"])].groupby(["ckpt_id", "arm"]).d_sr_id.mean().unstack()
H = g.max(axis=1).rename("H"); meta = pd.DataFrame({"ckpt_id": H.index}); meta["task"] = meta.ckpt_id.str.split("/").str[0].str.split("@").str[0]; meta["cls"] = meta.ckpt_id.map(lambda c: c.split("/")[1][:2].upper()); meta["H"] = H.values; meta["keep"] = meta.H >= 0.10
meta = meta[~meta.ckpt_id.str.contains("reparam|@w")]
out = ["# Checkpoint informativeness screen and attempt rates (benchmark v2 proposal; generated by scripts/analyze_screen.py)", "", "## 1 Screen on scripted controls only (H = best scripted gain; keep if H >= 0.10)", "", meta[meta.cls != "S0"].groupby(["task", "cls"]).agg(n=("keep", "size"), kept=("keep", "sum"), median_H=("H", "median")).round(2).to_markdown(), ""]
# validation on the main study
t0, mw = get("main-v1-t0"), get("main-v1-mw"); rows = []
for name, d, arms in (("Tier-0", t0, ["sonnet55-medium", "sonnet55-high", "opus55-medium", "opus55-high"]), ("Meta-World", mw, ["sonnet55-medium", "opus55-medium"])):
    P = d.pivot_table(index="ckpt_id", columns="arm", values="d_sr_id")[arms]; keep = meta.set_index("ckpt_id")["keep"].reindex(P.index)
    for lab, m in (("kept (H>=0.10)", keep.fillna(False).to_numpy()), ("dropped", ~keep.fillna(False).to_numpy())):
        Q = P[m]
        if len(Q): rows.append([name, lab, len(Q), float((Q.max(axis=1) - Q.min(axis=1)).mean()), float(((Q.max(axis=1) - Q.min(axis=1)) < 0.05).mean()), float((Q.abs() < 0.02).all(axis=1).mean())])
out += ["## 2 Validation on the completed main study (post-hoc; 16 Tier-0 and 17 Meta-World checkpoints)", "", "| tier | group | n | mean arm spread | share with spread <0.05 | share with all arms ~0 |", "|---|---|---|---|---|---|"] + [f"| {r[0]} | {r[1]} | {r[2]} | {r[3]:.2f} | {r[4]:.0%} | {r[5]:.0%} |" for r in rows] + [""]
# attempt rates
def att(d, tier):
    r = []
    for _, x in d.iterrows():
        j = json.loads(Path(x.path).read_text()); ps = [q["patch_status"] for q in j["rounds"]]; r.append(dict(tier=tier, arm=x.arm, attempted=ps.count("valid_changed") > 0, changed_rounds=ps.count("valid_changed") / len(ps), regress=x.regression_id))
    return pd.DataFrame(r)
A = pd.concat([att(t0, "Tier-0"), att(mw, "Meta-World")]).groupby(["tier", "arm"]).agg(runs=("attempted", "size"), attempt_rate=("attempted", "mean"), changed_round_share=("changed_rounds", "mean"), mean_regression=("regress", "mean")).round(2)
out += ["## 3 Attempt rate (share of runs with at least one real edit), the share of rounds with a real edit, and regression", "", A.to_markdown(), ""]
(ROOT / "reports/CHECKPOINT_SCREEN.md").write_text("\n".join(out)); print("\n".join(out))
